    usort($sorted_set, function($a, $b) use ($order) {
        if ($order === 'asc') {
            return $a['age'] <=> $b['age'];
        } elseif ($order === 'desc') {
            return $b['age'] <=> $a['age'];
        } else {
            throw new InvalidArgumentException('Invalid order: must be either "asc" or "desc".');
        }
    });

    return $sorted_set;
}

